r(--we-danger-border);\n  background: var(--we-danger-bg);\n  color: var(--we-danger-text);\n}\n\n.we-api-routing {\n  display: grid;\n  grid-template-columns: minmax(0, 0.7fr) minmax(0, 1.3fr);\n  gap: 12px 18px;\n  min-width: 0;\n}\n\n.we-api-routing-options {\n  display: grid;\n  grid-column: span 2;\n  gap: 5px;\n  min-width: 0;\n  padding-top: 2px;\n}\n\n.we-api-routing-options .we-api-field-head {\n  margin-bottom: 2px;\n}\n\n.we-api-fallbacks {\n  display: grid;\n  min-width: 0;\n  gap: 6px;\n  color: var(--we-muted);\n  font-size: 11px;\n}\n\n.we-api-route-list {\n  display: grid;\n  gap: 5px;\n}\n\n.we-api-route-row {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  min-width: 0;\n  min-height: 31px;\n  padding: 3px 7px;\n  border: 1px solid var(--we-border);\n  border-radius: 7px;\n  background: var(--we-input);\n}\n\n.we-api-route-toggle {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  min-width: 0;\n  flex: 1;\n  color: var(--we-text);\n  cursor: pointer;\n  font-size: 11px;\n}\n\n.we-api-route-toggle span {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.we-api-route-order {\n  flex: none;\n  color: var(--we-muted);\n  font-size: 10px;\n  white-space: nowrap;\n}\n\n.we-route-move {\n  width: 23px;\n  height: 23px;\n  border: 1px solid var(--we-border);\n  border-radius: 5px;\n  background: transparent;\n  color: var(--we-muted);\n  cursor: pointer;\n}\n\n.we-route-move:disabled {\n  cursor: default;\n  opacity: 0.4;\n}\n\n.we-api-option {\n  color: var(--we-text) !important;\n}\n\n.we-api-route-summary {\n  display: grid;\n  gap: 4px;\n  overflow-wrap: anywhere;\n  padding: 9px 11px;\n  border-radius: 8px;\n  background: var(--we-tint);\n  color: var(--we-muted);\n  font-size: 11px;\n}\n\n.we-api-route-summary strong {\n  overflow-wrap: anywhere;\n  color: var(--we-text);\n  word-break: break-word;\n}\n\n.we-api-bridge {\n  padding-bottom: 13px;\n}\n\n.we-api-bridge-status {\n  display